/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    fn state<T>(slot: &'static crate::core::feature_hooks::feature_hooks::FeatureHookSlot<T>) -> (&'static str, bool) {
        (slot.name(), slot.is_installed())
    }
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_ui_low::feature_hook_slots());
    slots.push(state(&crate::core::lib::sai::modules::sai_debugger::bottom_sheet_debug_catalog_hooks::BOTTOM_SHEET_DEBUG_CATALOG_HOOKS));
    slots.push(state(&crate::modules::music::pages::now_playing::now_playing_aside_hooks::NOW_PLAYING_ASIDE_HOOKS));
    slots.push(state(&crate::modules::stickers::components::sticker_asset_composer_hooks::STICKER_ASSET_COMPOSER_HOOKS));
    slots
}
